pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        vm.assume(receiver.code.length == 0); // plain EOA always accepts transfer
        vm.assume(amount > 0);
        vm.deal(address(c), amount);

        uint256 before = receiver.balance;
        vm.prank(address(this)); // test contract is owner (deployer in setUp)
        bool ok;
        try c.sendTo(receiver, amount) { ok = true; } catch { ok = false; }

        assertTrue(ok && receiver.balance - before == amount);
    }
}

