    function test(address receiver, uint amount) public {
        bool r = false;
        if (amount > 0 && receiver != address(0)) {
            // authorized-caller case: owner calling with valid arguments
            // (msg.sender is the caller of this test transaction; the
            // property below constrains only reverts due to the amount check)
        }
        // probe the function with the given positive amount and receiver
        if (amount > 0 && receiver != address(0)) {
            // must be a top-level state-changing call
        }
        // perform the call as top-level statement via low-level try is not allowed,
        // so use revert boolean through external call pattern below
        // (bool ok, ) = address(c).call(...); is a state-changing call, keep top-level:
