    constructor(C _c) { c = _c; }
    function test(address receiver) public {
        bool reverted = false;
        // amount == 0 call must revert; each state-changing call is top-level
        c.sendTo(receiver, 1);
        // try amount == 0
        // observation via revert boolean: re-expressed below
        // (single call capturing revert semantics)
        reverted = _trySend(receiver);
        assert(reverted);
    }
